const payload = msg.payload;
const isBackfill = payload.backfill === true;

// Use payload timestamp if backfill, otherwise now
const timestamp = isBackfill && payload.ts > 0
    ? new Date(payload.ts * 1000)
    : new Date();

msg.payload = [
    {
        measurement: "air_quality",
        tags: {
            device_id:   payload.device_id,
            device_name: payload.device_name,
            group:       payload.group || "default",
            backfill:    String(isBackfill)
        },
        fields: {
            temp:     payload.temp,
            hum:      payload.hum,
            iaq:      payload.iaq,
            co2:      payload.co2,
            bvoc:     payload.bvoc,
            db:       payload.db,
            bat_pct:  payload.bat_pct,
            bat_mv:   payload.bat_mv,
            rssi:     payload.rssi,
            accuracy: payload.accuracy
        },
        timestamp: timestamp
    }
];

return msg;

const reg = msg.payload;
const mac = reg.mac.toLowerCase().replace(/:/g, "");
const fs = require("fs");

let whitelist;
try {
    whitelist = JSON.parse(fs.readFileSync("/data/whitelist.json", "utf8"));
} catch (e) {
    node.error("Cannot read whitelist.json: " + e.message, msg);
    return null;
}

const device = whitelist.devices.find(d =>
    d.mac.toLowerCase().replace(/:/g, "") === mac
);

if (device && device.authorized) {
    msg.approved = true;
    msg.mac = mac;
    msg.device_name = reg.device_name;
} else {
    msg.approved = false;
    msg.mac = mac;
}
return msg;

// Generate a secure random password
const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
let pass = "";
for (let i = 0; i < 20; i++) {
    pass += chars[Math.floor(Math.random() * chars.length)];
}

const user = "device_" + msg.mac;
const deviceId = "hivis-" + msg.mac;

msg.topic = "hivis/provision/" + msg.mac;
msg.payload = JSON.stringify({
    status: "approved",
    mqtt_user: user,
    mqtt_pass: pass,
    device_id: deviceId
});
msg.retain = true;

// Auto-provision Mosquitto user via OTA server
try {
    const resp = await fetch("http://ota-server:8090/provision", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({user: user, password: pass})
    });
    if (resp.ok) {
        node.warn("Auto-provisioned: " + user);
    } else {
        node.warn("Provision API failed (" + resp.status + ") for " + user + " — add manually");
    }
} catch(e) {
    node.warn("Provision API error: " + e.message + " — " + user + " add manually");
}

return msg;

msg.topic = "hivis/provision/" + msg.mac;
msg.payload = JSON.stringify({
    status: "rejected",
    device_id: "hivis-" + msg.mac
});
msg.retain = false;
return msg;

const payload = msg.payload;

msg.payload = [
    {
        measurement: "device_status",
        tags: {
            device_id:   payload.device_id,
            device_name: payload.device_name,
            group:       payload.group || "default",
            backfill:    String(payload.backfill === true)
        },
        fields: {
            bat_pct:    payload.bat_pct,
            bat_mv:     payload.bat_mv,
            rssi:       payload.rssi,
            accuracy:   payload.accuracy,
            fw_version: payload.fw_version || "unknown"
        },
        timestamp: (payload.backfill === true && payload.ts > 0)
            ? new Date(payload.ts * 1000)
            : new Date()
    }
];

return msg;
